# -----------------------------------------------------------------------------
# Configuration lookup helpers
# -----------------------------------------------------------------------------

def _get_config_value(
    candidate_names: Sequence[str],
    default: T,
) -> T:
    """
    Retrieve the first available value from the configuration module.

    Parameters
    ----------
    candidate_names : sequence of str
        Candidate configuration attribute names.
    default : T
        Fallback value.

    Returns
    -------
    T
        Configured value or ``default``.

    Notes
    -----
    This helper intentionally accepts multiple names to preserve compatibility
    with possible future changes in ``config.py``.
    """

    for candidate_name in candidate_names:
        try:
            value = getattr(
                config,
                candidate_name,
            )

        except (
            AttributeError,
            TypeError,
        ):
            continue

        if value is not None:
            return value

    return default


def _coerce_positive_float(
    value: Any,
    *,
    name: str,
    default: np.float64,
    allow_zero: bool = False,
) -> np.float64:
    """
    Convert a configuration value to a finite positive float.

    Parameters
    ----------
    value : Any
        Candidate numeric value.
    name : str
        Human-readable parameter name.
    default : numpy.float64
        Fallback value.
    allow_zero : bool, optional
        Whether zero is accepted.

    Returns
    -------
    numpy.float64
        Validated numeric value.
    """

    try:
        numeric_value = np.float64(
            value
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ):
        try:
            _LOGGER.warning(
                f"Invalid configured value for {name!r}; "
                f"using default {float(default):g}."
            )

        except Exception:
            pass

        return np.float64(
            default
        )

    if not np.isfinite(
        numeric_value
    ):
        try:
            _LOGGER.warning(
                f"Non-finite configured value for {name!r}; "
                f"using default {float(default):g}."
            )

        except Exception:
            pass

        return np.float64(
            default
        )

    minimum_allowed = (
        np.float64(0.0)
        if allow_zero
        else MINIMUM_POSITIVE_DISTANCE
    )

    if numeric_value < minimum_allowed:
        try:
            _LOGGER.warning(
                f"Configured value for {name!r} is outside "
                f"the accepted range; using default "
                f"{float(default):g}."
            )

        except Exception:
            pass

        return np.float64(
            default
        )

    return numeric_value


def _coerce_angle(
    value: Any,
    *,
    name: str,
    default: np.float64,
) -> np.float64:
    """
    Convert a configuration value to a valid angle in degrees.

    Parameters
    ----------
    value : Any
        Candidate angle.
    name : str
        Human-readable parameter name.
    default : numpy.float64
        Fallback angle.

    Returns
    -------
    numpy.float64
        Angle between zero and 180 degrees.
    """

    try:
        numeric_value = np.float64(
            value
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ):
        try:
            _LOGGER.warning(
                f"Invalid configured angle for {name!r}; "
                f"using default {float(default):g} degrees."
            )

        except Exception:
            pass

        return np.float64(
            default
        )

    if (
        not np.isfinite(
            numeric_value
        )
        or numeric_value
        < MINIMUM_VALID_ANGLE_DEGREES
        or numeric_value
        > MAXIMUM_VALID_ANGLE_DEGREES
    ):
        try:
            _LOGGER.warning(
                f"Configured angle for {name!r} is outside "
                "the valid interval [0, 180]; "
                f"using default {float(default):g} degrees."
            )

        except Exception:
            pass

        return np.float64(
            default
        )

    return numeric_value


def _coerce_positive_integer(
    value: Any,
    *,
    name: str,
    default: int,
) -> int:
    """
    Convert a configuration value to a positive integer.

    Parameters
    ----------
    value : Any
        Candidate value.
    name : str
        Human-readable parameter name.
    default : int
        Fallback integer.

    Returns
    -------
    int
        Positive integer.
    """

    if isinstance(
        value,
        bool,
    ):
        return int(
            default
        )

    try:
        integer_value = int(
            value
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ):
        try:
            _LOGGER.warning(
                f"Invalid configured value for {name!r}; "
                f"using default {default}."
            )

        except Exception:
            pass

        return int(
            default
        )

    if integer_value <= 0:
        try:
            _LOGGER.warning(
                f"Configured value for {name!r} must be positive; "
                f"using default {default}."
            )

        except Exception:
            pass

        return int(
            default
        )

    return integer_value


