# -----------------------------------------------------------------------------
# Local normalization helpers
# -----------------------------------------------------------------------------

def _freeze_metadata(
    metadata: Optional[
        Mapping[
            str,
            Any,
        ]
    ],
) -> Mapping[
    str,
    Any,
]:
    """
    Create an immutable shallow copy of a metadata mapping.

    Parameters
    ----------
    metadata : mapping or None
        Metadata to normalize.

    Returns
    -------
    mapping
        Immutable metadata mapping.

    Raises
    ------
    TypeError
        If ``metadata`` is not a mapping.
    """

    if metadata is None:
        return _EMPTY_METADATA

    if not isinstance(
        metadata,
        Mapping,
    ):
        raise TypeError(
            "Metadata must be a mapping or None."
        )

    if not metadata:
        return _EMPTY_METADATA

    return MappingProxyType(
        dict(
            metadata
        )
    )


def _optional_float64(
    value: Optional[
        Number
    ],
    *,
    name: str,
    minimum: Optional[
        Number
    ] = None,
    maximum: Optional[
        Number
    ] = None,
) -> Optional[
    np.float64
]:
    """
    Normalize an optional numeric value as ``numpy.float64``.

    Parameters
    ----------
    value : Number or None
        Numeric value.
    name : str
        Human-readable field name.
    minimum : Number or None, optional
        Inclusive minimum value.
    maximum : Number or None, optional
        Inclusive maximum value.

    Returns
    -------
    numpy.float64 or None
        Normalized value.

    Raises
    ------
    TypeError
        If ``value`` is not numeric.
    ValueError
        If ``value`` is non-finite or outside the accepted interval.
    """

    if value is None:
        return None

    if isinstance(
        value,
        (
            bool,
            np.bool_,
        ),
    ):
        raise TypeError(
            f"{name} must be numeric, not boolean."
        )

    try:
        normalized = np.float64(
            value
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ) as error:
        raise TypeError(
            f"{name} must be a valid numeric value."
        ) from error

    if not np.isfinite(
        normalized
    ):
        raise ValueError(
            f"{name} must be finite."
        )

    if (
        minimum is not None
        and normalized
        < np.float64(
            minimum
        )
    ):
        raise ValueError(
            f"{name} must be greater than or equal to "
            f"{float(np.float64(minimum)):g}."
        )

    if (
        maximum is not None
        and normalized
        > np.float64(
            maximum
        )
    ):
        raise ValueError(
            f"{name} must be less than or equal to "
            f"{float(np.float64(maximum)):g}."
        )

    return normalized


def _optional_nonnegative_integer(
    value: Optional[
        Number
    ],
    *,
    name: str,
) -> Optional[
    int
]:
    """
    Normalize an optional non-negative integer.

    Parameters
    ----------
    value : Number or None
        Candidate index.
    name : str
        Human-readable field name.

    Returns
    -------
    int or None
        Normalized integer.

    Raises
    ------
    TypeError
        If ``value`` is not integer-like.
    ValueError
        If ``value`` is negative.
    """

    if value is None:
        return None

    if isinstance(
        value,
        (
            bool,
            np.bool_,
        ),
    ):
        raise TypeError(
            f"{name} must be an integer, not boolean."
        )

    try:
        normalized_float = np.float64(
            value
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ) as error:
        raise TypeError(
            f"{name} must be an integer or None."
        ) from error

    if (
        not np.isfinite(
            normalized_float
        )
        or not float(
            normalized_float
        ).is_integer()
    ):
        raise TypeError(
            f"{name} must be an integer or None."
        )

    normalized = int(
        normalized_float
    )

    if normalized < 0:
        raise ValueError(
            f"{name} cannot be negative."
        )

    return normalized


def _normalize_residue_key(
    key: Optional[
        ResidueContactKey
    ],
) -> Optional[
    ResidueContactKey
]:
    """
    Normalize an optional residue contact key.

    Parameters
    ----------
    key : ResidueContactKey or None
        Residue key in ``(name, number, chain_id)`` form.

    Returns
    -------
    ResidueContactKey or None
        Normalized key.

    Raises
    ------
    TypeError
        If the key does not have three components.
    """

    if key is None:
        return None

    if (
        not isinstance(
            key,
            (
                tuple,
                list,
            ),
        )
        or len(
            key
        )
        != 3
    ):
        raise TypeError(
            "A residue key must contain exactly three values: "
            "(name, number, chain_id)."
        )

    residue_name = str(
        key[
            0
        ]
        or ""
    ).strip().upper()

    try:
        residue_number = int(
            key[
                1
            ]
        )

    except (
        TypeError,
        ValueError,
        OverflowError,
    ) as error:
        raise TypeError(
            "The residue number in a residue key must be an integer."
        ) from error

    chain_id = str(
        key[
            2
        ]
        or ""
    ).strip()

    return (
        residue_name,
        residue_number,
        chain_id,
    )


def _safe_atom_identifier(
    atom: Optional[
        AtomLike
    ],
) -> Optional[
    str
]:
    """
    Return an atom identifier without propagating helper errors.

    Parameters
    ----------
    atom : atom-like or None
        Atom to identify.

    Returns
    -------
    str or None
        Atom identifier.
    """

    if atom is None:
        return None

    try:
        identifier = get_atom_identifier(
            atom
        )

    except Exception:
        try:
            identifier = get_atom_name(
                atom
            )

        except Exception:
            identifier = repr(
                atom
            )

    if identifier is None:
        return None

    return str(
        identifier
    )


def _safe_residue_key_from_atom(
    atom: Optional[
        AtomLike
    ],
) -> Optional[
    ResidueContactKey
]:
    """
    Resolve a residue contact key from an atom defensively.

    Parameters
    ----------
    atom : atom-like or None
        Atom whose residue should be identified.

    Returns
    -------
    ResidueContactKey or None
        Residue key when available.
    """

    if atom is None:
        return None

    try:
        residue = get_atom_residue(
            atom
        )

    except Exception:
        return None

    if residue is None:
        return None

    try:
        return get_residue_contact_key(
            residue
        )

    except Exception:
        return None


