# Hydrogen-bond geometry
# -----------------------------------------------------------------------------

@dataclass(
    frozen=True,
    slots=True,
)
class HydrogenBondGeometry:
    """
    Geometric measurements associated with a hydrogen bond.

    Parameters
    ----------
    donor_acceptor_distance : Number
        Distance between donor and acceptor atoms in angstroms.
    hydrogen_acceptor_distance : Number or None, optional
        Distance between the explicit hydrogen and acceptor in angstroms.
        This value is normally unavailable for inferred hydrogen bonds.
    donor_hydrogen_distance : Number or None, optional
        Covalent donor-hydrogen distance in angstroms.
    dha_angle : Number or None, optional
        Donor-hydrogen-acceptor angle in degrees.
    donor_angle : Number or None, optional
        Auxiliary donor-side angle used by inferred geometric models.
    acceptor_angle : Number or None, optional
        Auxiliary acceptor-side angle.
    metadata : mapping, optional
        Additional geometric information.

    Notes
    -----
    All stored floating-point values are normalized to ``numpy.float64``.
    """

    donor_acceptor_distance: np.float64

    hydrogen_acceptor_distance: Optional[
        np.float64
    ] = None

    donor_hydrogen_distance: Optional[
        np.float64
    ] = None

    dha_angle: Optional[
        np.float64
    ] = None

    donor_angle: Optional[
        np.float64
    ] = None

    acceptor_angle: Optional[
        np.float64
    ] = None

    metadata: Mapping[
        str,
        Any,
    ] = field(
        default_factory=lambda: _EMPTY_METADATA,
        repr=False,
        compare=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Validate and normalize geometric measurements."""

        donor_acceptor_distance = (
            _optional_float64(
                self.donor_acceptor_distance,
                name="donor-acceptor distance",
                minimum=0.0,
            )
        )

        if donor_acceptor_distance is None:
            raise ValueError(
                "Donor-acceptor distance cannot be None."
            )

        object.__setattr__(
            self,
            "donor_acceptor_distance",
            donor_acceptor_distance,
        )

        object.__setattr__(
            self,
            "hydrogen_acceptor_distance",
            _optional_float64(
                self.hydrogen_acceptor_distance,
                name="hydrogen-acceptor distance",
                minimum=0.0,
            ),
        )

        object.__setattr__(
            self,
            "donor_hydrogen_distance",
            _optional_float64(
                self.donor_hydrogen_distance,
                name="donor-hydrogen distance",
                minimum=0.0,
            ),
        )

        for field_name in (
            "dha_angle",
            "donor_angle",
            "acceptor_angle",
        ):
            object.__setattr__(
                self,
                field_name,
                _optional_float64(
                    getattr(
                        self,
                        field_name,
                    ),
                    name=field_name.replace(
                        "_",
                        " ",
                    ),
                    minimum=MINIMUM_VALID_ANGLE_DEGREES,
                    maximum=MAXIMUM_VALID_ANGLE_DEGREES,
                ),
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_metadata(
                self.metadata
            ),
        )

    @property
    def has_explicit_hydrogen_geometry(
        self,
    ) -> bool:
        """
        Whether explicit hydrogen-bond geometry is available.

        Returns
        -------
        bool
            ``True`` when both H...A distance and D-H...A angle exist.
        """

        return (
            self.hydrogen_acceptor_distance
            is not None
            and self.dha_angle
            is not None
        )

    @property
    def has_angular_geometry(
        self,
    ) -> bool:
        """
        Whether at least one angular measurement is available.

        Returns
        -------
        bool
            Angular-data availability.
        """

        return any(
            value is not None
            for value in (
                self.dha_angle,
                self.donor_angle,
                self.acceptor_angle,
            )
        )

    @property
    def linearity_deviation(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the deviation of D-H...A from linear geometry.

        Returns
        -------
        numpy.float64 or None
            ``180° - D-H...A`` when the angle is available.
        """

        if self.dha_angle is None:
            return None

        return np.float64(
            STRAIGHT_ANGLE_DEGREES
            - self.dha_angle
        )

    def to_dict(
        self,
    ) -> Dict[
        str,
        Any,
    ]:
        """
        Serialize the geometry.

        Returns
        -------
        dict
            JSON-compatible geometric summary.
        """

        return {
            "donor_acceptor_distance": float(
                self.donor_acceptor_distance
            ),
            "hydrogen_acceptor_distance": (
                None
                if self.hydrogen_acceptor_distance is None
                else float(
                    self.hydrogen_acceptor_distance
                )
            ),
            "donor_hydrogen_distance": (
                None
                if self.donor_hydrogen_distance is None
                else float(
                    self.donor_hydrogen_distance
                )
            ),
            "dha_angle": (
                None
                if self.dha_angle is None
                else float(
                    self.dha_angle
                )
            ),
            "donor_angle": (
                None
                if self.donor_angle is None
                else float(
                    self.donor_angle
                )
            ),
            "acceptor_angle": (
                None
                if self.acceptor_angle is None
                else float(
                    self.acceptor_angle
                )
            ),
            "has_explicit_hydrogen_geometry": (
                self.has_explicit_hydrogen_geometry
            ),
            "linearity_deviation": (
                None
                if self.linearity_deviation is None
                else float(
                    self.linearity_deviation
                )
            ),
            "metadata": (
                _serialize_hbond_statistics_value(
                    self.metadata
                )
            ),
        }


# -----------------------------------------------------------------------------
# Individual hydrogen-bond result
# -----------------------------------------------------------------------------

@dataclass(
    frozen=True,
    slots=True,
)
class HydrogenBond:
    """
    Representation of one donor-hydrogen-acceptor interaction.

    Parameters
    ----------
    donor : atom-like
        Donor atom.
    acceptor : atom-like
        Acceptor atom.
    geometry : HydrogenBondGeometry
        Calculated interaction geometry.
    hydrogen : atom-like or None, optional
        Explicit hydrogen atom. It is ``None`` for inferred interactions.
    mode : HydrogenBondMode, optional
        Explicit or inferred analysis mode.
    direction : HydrogenBondDirection, optional
        Whether the ligand or receptor acts as donor.
    classification : HydrogenBondClassification, optional
        Geometric strength classification.
    donor_index : int or None, optional
        Donor index in its analyzed atom collection.
    hydrogen_index : int or None, optional
        Hydrogen index in its analyzed atom collection.
    acceptor_index : int or None, optional
        Acceptor index in its analyzed atom collection.
    donor_residue : residue-like or None, optional
        Donor parent residue.
    acceptor_residue : residue-like or None, optional
        Acceptor parent residue.
    donor_residue_key : ResidueContactKey or None, optional
        Normalized donor residue key.
    acceptor_residue_key : ResidueContactKey or None, optional
        Normalized acceptor residue key.
    metadata : mapping, optional
        Additional interaction metadata.
    """

    donor: AtomLike
    acceptor: AtomLike
    geometry: HydrogenBondGeometry

    hydrogen: Optional[
        AtomLike
    ] = None

    mode: HydrogenBondMode = (
        HBOND_MODE_INFERRED
    )

    direction: HydrogenBondDirection = (
        HBOND_DIRECTION_UNKNOWN
    )

    classification: HydrogenBondClassification = (
        HBOND_TYPE_UNKNOWN
    )

    donor_index: Optional[
        int
    ] = None

    hydrogen_index: Optional[
        int
    ] = None

    acceptor_index: Optional[
        int
    ] = None

    donor_residue: Optional[
        ResidueLike
    ] = None

    acceptor_residue: Optional[
        ResidueLike
    ] = None

    donor_residue_key: Optional[
        ResidueContactKey
    ] = None

    acceptor_residue_key: Optional[
        ResidueContactKey
    ] = None

    metadata: Mapping[
        str,
        Any,
    ] = field(
        default_factory=lambda: _EMPTY_METADATA,
        repr=False,
        compare=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Validate and normalize the interaction."""

        if self.donor is None:
            raise ValueError(
                "Hydrogen-bond donor cannot be None."
            )

        if self.acceptor is None:
            raise ValueError(
                "Hydrogen-bond acceptor cannot be None."
            )

        if self.donor is self.acceptor:
            raise ValueError(
                "Hydrogen-bond donor and acceptor must be "
                "different atoms."
            )

        if not isinstance(
            self.geometry,
            HydrogenBondGeometry,
        ):
            raise TypeError(
                "geometry must be a HydrogenBondGeometry instance."
            )

        normalized_mode = (
            validate_hydrogen_bond_mode(
                self.mode
            )
        )

        normalized_direction = (
            validate_hydrogen_bond_direction(
                self.direction
            )
        )

        normalized_classification = (
            validate_hydrogen_bond_classification(
                self.classification
            )
        )

        if (
            normalized_mode
            == HBOND_MODE_EXPLICIT
            and self.hydrogen is None
        ):
            raise ValueError(
                "Explicit hydrogen-bond mode requires a "
                "hydrogen atom."
            )

        if (
            normalized_mode
            == HBOND_MODE_INFERRED
            and self.hydrogen is not None
        ):
            normalized_mode = (
                HBOND_MODE_EXPLICIT
            )

        if (
            self.hydrogen is not None
            and (
                self.hydrogen is self.donor
                or self.hydrogen is self.acceptor
            )
        ):
            raise ValueError(
                "The hydrogen atom must differ from the donor "
                "and acceptor atoms."
            )

        object.__setattr__(
            self,
            "mode",
            normalized_mode,
        )

        object.__setattr__(
            self,
            "direction",
            normalized_direction,
        )

        object.__setattr__(
            self,
            "classification",
            normalized_classification,
        )

        object.__setattr__(
            self,
            "donor_index",
            _optional_nonnegative_integer(
                self.donor_index,
                name="donor index",
            ),
        )

        object.__setattr__(
            self,
            "hydrogen_index",
            _optional_nonnegative_integer(
                self.hydrogen_index,
                name="hydrogen index",
            ),
        )

        object.__setattr__(
            self,
            "acceptor_index",
            _optional_nonnegative_integer(
                self.acceptor_index,
                name="acceptor index",
            ),
        )

        donor_residue = self.donor_residue

        if donor_residue is None:
            try:
                donor_residue = (
                    get_atom_residue(
                        self.donor
                    )
                )

            except Exception:
                donor_residue = None

        acceptor_residue = self.acceptor_residue

        if acceptor_residue is None:
            try:
                acceptor_residue = (
                    get_atom_residue(
                        self.acceptor
                    )
                )

            except Exception:
                acceptor_residue = None

        object.__setattr__(
            self,
            "donor_residue",
            donor_residue,
        )

        object.__setattr__(
            self,
            "acceptor_residue",
            acceptor_residue,
        )

        donor_key = (
            _normalize_residue_key(
                self.donor_residue_key
            )
        )

        if donor_key is None:
            donor_key = (
                _safe_residue_key_from_atom(
                    self.donor
                )
            )

        acceptor_key = (
            _normalize_residue_key(
                self.acceptor_residue_key
            )
        )

        if acceptor_key is None:
            acceptor_key = (
                _safe_residue_key_from_atom(
                    self.acceptor
                )
            )

        object.__setattr__(
            self,
            "donor_residue_key",
            donor_key,
        )

        object.__setattr__(
            self,
            "acceptor_residue_key",
            acceptor_key,
        )

        object.__setattr__(
            self,
            "metadata",
            _freeze_metadata(
                self.metadata
            ),
        )

    @property
    def donor_acceptor_distance(
        self,
    ) -> np.float64:
        """
        Return the donor-acceptor distance.

        Returns
        -------
        numpy.float64
            D...A distance in angstroms.
        """

        return (
            self.geometry
            .donor_acceptor_distance
        )

    @property
    def hydrogen_acceptor_distance(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the hydrogen-acceptor distance.

        Returns
        -------
        numpy.float64 or None
            H...A distance in angstroms.
        """

        return (
            self.geometry
            .hydrogen_acceptor_distance
        )

    @property
    def dha_angle(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the donor-hydrogen-acceptor angle.

        Returns
        -------
        numpy.float64 or None
            D-H...A angle in degrees.
        """

        return self.geometry.dha_angle

    @property
    def atom_pair(
        self,
    ) -> DonorAcceptorPair:
        """
        Return the donor-acceptor atom pair.

        Returns
        -------
        DonorAcceptorPair
            Donor and acceptor atoms.
        """

        return (
            self.donor,
            self.acceptor,
        )

    @property
    def atom_triple(
        self,
    ) -> Tuple[
        AtomLike,
        Optional[
            AtomLike
        ],
        AtomLike,
    ]:
        """
        Return donor, hydrogen and acceptor atoms.

        Returns
        -------
        tuple
            ``(donor, hydrogen, acceptor)``.
        """

        return (
            self.donor,
            self.hydrogen,
            self.acceptor,
        )

    @property
    def index_pair(
        self,
    ) -> Tuple[
        Optional[
            int
        ],
        Optional[
            int
        ],
    ]:
        """
        Return donor and acceptor indices.

        Returns
        -------
        tuple
            Donor and acceptor indices.
        """

        return (
            self.donor_index,
            self.acceptor_index,
        )

    @property
    def index_triple(
        self,
    ) -> Tuple[
        Optional[
            int
        ],
        Optional[
            int
        ],
        Optional[
            int
        ],
    ]:
        """
        Return donor, hydrogen and acceptor indices.

        Returns
        -------
        tuple
            D-H-A indices.
        """

        return (
            self.donor_index,
            self.hydrogen_index,
            self.acceptor_index,
        )

    @property
    def is_explicit(
        self,
    ) -> bool:
        """
        Whether this bond uses an explicit hydrogen.

        Returns
        -------
        bool
            Explicit-mode status.
        """

        return (
            self.mode
            == HBOND_MODE_EXPLICIT
            and self.hydrogen is not None
        )

    @property
    def is_inferred(
        self,
    ) -> bool:
        """
        Whether this bond was geometrically inferred.

        Returns
        -------
        bool
            Inferred-mode status.
        """

        return not self.is_explicit

    @property
    def is_strong(
        self,
    ) -> bool:
        """
        Whether the bond is classified as strong.

        Returns
        -------
        bool
            Strong-classification status.
        """

        return (
            self.classification
            == HBOND_TYPE_STRONG
        )

    @property
    def is_ligand_donor(
        self,
    ) -> bool:
        """
        Whether the ligand acts as donor.

        Returns
        -------
        bool
            Ligand-donor status.
        """

        return (
            self.direction
            == HBOND_DIRECTION_LIGAND_DONOR
        )

    @property
    def is_receptor_donor(
        self,
    ) -> bool:
        """
        Whether the receptor acts as donor.

        Returns
        -------
        bool
            Receptor-donor status.
        """

        return (
            self.direction
            == HBOND_DIRECTION_RECEPTOR_DONOR
        )

    @property
    def identifier(
        self,
    ) -> HydrogenBondIdentifier:
        """
        Return a stable descriptive hydrogen-bond identifier.

        Returns
        -------
        HydrogenBondIdentifier
            Donor, acceptor and optional hydrogen identifiers.
        """

        donor_identifier = (
            _safe_atom_identifier(
                self.donor
            )
            or "unknown_donor"
        )

        acceptor_identifier = (
            _safe_atom_identifier(
                self.acceptor
            )
            or "unknown_acceptor"
        )

        hydrogen_identifier = (
            _safe_atom_identifier(
                self.hydrogen
            )
        )

        return (
            donor_identifier,
            acceptor_identifier,
            hydrogen_identifier,
        )

    def to_dict(
        self,
        *,
        include_atoms: bool = False,
    ) -> Dict[
        str,
        Any,
    ]:
        """
        Serialize the hydrogen bond.

        Parameters
        ----------
        include_atoms : bool, optional
            Whether raw atom and residue objects should be included.

        Returns
        -------
        dict
            Serializable interaction representation.
        """

        result: Dict[
            str,
            Any,
        ] = {
            "identifier": self.identifier,
            "donor": _safe_atom_identifier(
                self.donor
            ),
            "hydrogen": _safe_atom_identifier(
                self.hydrogen
            ),
            "acceptor": _safe_atom_identifier(
                self.acceptor
            ),
            "donor_identifier": (
                _safe_atom_identifier(
                    self.donor
                )
            ),
            "hydrogen_identifier": (
                _safe_atom_identifier(
                    self.hydrogen
                )
            ),
            "acceptor_identifier": (
                _safe_atom_identifier(
                    self.acceptor
                )
            ),
            "mode": self.mode,
            "direction": self.direction,
            "classification": (
                self.classification
            ),
            "donor_index": self.donor_index,
            "hydrogen_index": (
                self.hydrogen_index
            ),
            "acceptor_index": (
                self.acceptor_index
            ),
            "donor_residue_key": (
                self.donor_residue_key
            ),
            "acceptor_residue_key": (
                self.acceptor_residue_key
            ),
            "geometry": (
                self.geometry.to_dict()
            ),
            "metadata": (
                _serialize_hbond_statistics_value(
                    self.metadata
                )
            ),
        }

        if include_atoms:
            result.update(
                {
                    "donor": self.donor,
                    "hydrogen": self.hydrogen,
                    "acceptor": self.acceptor,
                    "donor_residue": (
                        self.donor_residue
                    ),
                    "acceptor_residue": (
                        self.acceptor_residue
                    ),
                }
            )

        return result


# -----------------------------------------------------------------------------
# Residue-level hydrogen-bond result
# -----------------------------------------------------------------------------

@dataclass(
    frozen=True,
    slots=True,
)
class ResidueHydrogenBond:
    """
    Hydrogen bonds associated with one residue.

    Parameters
    ----------
    residue : residue-like
        Grouped residue.
    key : ResidueContactKey
        Normalized residue key.
    hydrogen_bonds : sequence of HydrogenBond
        Hydrogen bonds involving the residue.
    side : str, optional
        Grouping side: ``"donor"``, ``"acceptor"`` or ``"receptor"``.
    metadata : mapping, optional
        Additional residue-level metadata.
    """

    residue: ResidueLike
    key: ResidueContactKey

    hydrogen_bonds: Sequence[
        HydrogenBond
    ] = field(
        default_factory=tuple
    )

    side: str = "receptor"

    metadata: Mapping[
        str,
        Any,
    ] = field(
        default_factory=lambda: _EMPTY_METADATA,
        repr=False,
        compare=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Validate and normalize residue-level data."""

        if self.residue is None:
            raise ValueError(
                "ResidueHydrogenBond.residue cannot be None."
            )

        normalized_key = (
            _normalize_residue_key(
                self.key
            )
        )

        if normalized_key is None:
            raise ValueError(
                "ResidueHydrogenBond.key cannot be None."
            )

        normalized_bonds = tuple(
            self.hydrogen_bonds
        )

        for index, hydrogen_bond in enumerate(
            normalized_bonds
        ):
            if not isinstance(
                hydrogen_bond,
                HydrogenBond,
            ):
                raise TypeError(
                    "All residue hydrogen-bond entries must be "
                    "HydrogenBond instances. Invalid entry at "
                    f"index {index}."
                )

        normalized_side = str(
            self.side
        ).strip().lower()

        valid_sides = {
            "donor",
            "acceptor",
            "ligand",
            "receptor",
            "either",
        }

        if normalized_side not in valid_sides:
            raise ValueError(
                f"Unsupported residue grouping side "
                f"{self.side!r}. Expected one of: "
                f"{', '.join(sorted(valid_sides))}."
            )

        object.__setattr__(
            self,
            "key",
            normalized_key,
        )

        object.__setattr__(
            self,
            "hydrogen_bonds",
            normalized_bonds,
        )

        object.__setattr__(
            self,
            "side",
            normalized_side,
        )

        object.__setattr__(
            self,
            "metadata",
            _freeze_metadata(
                self.metadata
            ),
        )

    @property
    def count(
        self,
    ) -> int:
        """Return the number of hydrogen bonds in the residue group."""

        return len(
            self.hydrogen_bonds
        )

    @property
    def hydrogen_bond_count(
        self,
    ) -> int:
        """
        Return the number of hydrogen bonds.

        Returns
        -------
        int
            Hydrogen-bond count.
        """

        return len(
            self.hydrogen_bonds
        )

    @property
    def minimum_distance(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the minimum donor-acceptor distance.

        Returns
        -------
        numpy.float64 or None
            Minimum distance.
        """

        if not self.hydrogen_bonds:
            return None

        return np.float64(
            min(
                hydrogen_bond
                .donor_acceptor_distance
                for hydrogen_bond
                in self.hydrogen_bonds
            )
        )

    @property
    def mean_distance(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the mean donor-acceptor distance.

        Returns
        -------
        numpy.float64 or None
            Mean distance.
        """

        if not self.hydrogen_bonds:
            return None

        return np.float64(
            np.mean(
                np.asarray(
                    [
                        hydrogen_bond
                        .donor_acceptor_distance
                        for hydrogen_bond
                        in self.hydrogen_bonds
                    ],
                    dtype=np.float64,
                )
            )
        )

    @property
    def maximum_dha_angle(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the largest available D-H...A angle.

        Returns
        -------
        numpy.float64 or None
            Maximum angle.
        """

        angles = [
            hydrogen_bond.dha_angle
            for hydrogen_bond
            in self.hydrogen_bonds
            if hydrogen_bond.dha_angle
            is not None
        ]

        if not angles:
            return None

        return np.float64(
            max(
                angles
            )
        )

    @property
    def classifications(
        self,
    ) -> FrozenSet[
        HydrogenBondClassification
    ]:
        """
        Return classifications represented in the group.

        Returns
        -------
        frozenset
            Hydrogen-bond classifications.
        """

        return frozenset(
            hydrogen_bond.classification
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def directions(
        self,
    ) -> FrozenSet[
        HydrogenBondDirection
    ]:
        """
        Return directions represented in the group.

        Returns
        -------
        frozenset
            Hydrogen-bond directions.
        """

        return frozenset(
            hydrogen_bond.direction
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def explicit_count(
        self,
    ) -> int:
        """
        Return the number of explicit hydrogen bonds.

        Returns
        -------
        int
            Explicit-bond count.
        """

        return sum(
            hydrogen_bond.is_explicit
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def inferred_count(
        self,
    ) -> int:
        """
        Return the number of inferred hydrogen bonds.

        Returns
        -------
        int
            Inferred-bond count.
        """

        return (
            self.hydrogen_bond_count
            - self.explicit_count
        )

    @property
    def moderate_count(
        self,
    ) -> int:
        """Return the number of moderate hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_MODERATE
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def weak_count(
        self,
    ) -> int:
        """Return the number of weak hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_WEAK
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def unknown_count(
        self,
    ) -> int:
        """Return the number of unclassified hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_UNKNOWN
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def strong_count(
        self,
    ) -> int:
        """
        Return the number of strong hydrogen bonds.

        Returns
        -------
        int
            Strong-bond count.
        """

        return sum(
            hydrogen_bond.is_strong
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def has_strong_bond(
        self,
    ) -> bool:
        """
        Whether the residue forms a strong hydrogen bond.

        Returns
        -------
        bool
            Strong-bond presence.
        """

        return self.strong_count > 0

    def bonds_by_classification(
        self,
        classification: str,
    ) -> Tuple[
        HydrogenBond,
        ...,
    ]:
        """
        Select residue bonds by classification.

        Parameters
        ----------
        classification : str
            Requested classification.

        Returns
        -------
        tuple of HydrogenBond
            Matching bonds.
        """

        normalized = (
            validate_hydrogen_bond_classification(
                classification
            )
        )

        return tuple(
            hydrogen_bond
            for hydrogen_bond
            in self.hydrogen_bonds
            if hydrogen_bond.classification
            == normalized
        )

    def to_dict(
        self,
        *,
        include_bonds: bool = True,
        include_atoms: bool = False,
    ) -> Dict[
        str,
        Any,
    ]:
        """
        Serialize the residue-level hydrogen-bond result.

        Parameters
        ----------
        include_bonds : bool, optional
            Whether individual bonds should be included.
        include_atoms : bool, optional
            Whether raw atom objects should be included in bond data.

        Returns
        -------
        dict
            Residue-level summary.
        """

        result: Dict[
            str,
            Any,
        ] = {
            "residue": (
                self.residue
                if include_atoms
                else self.key
            ),
            "key": self.key,
            "side": self.side,
            "hydrogen_bond_count": (
                self.hydrogen_bond_count
            ),
            "explicit_count": (
                self.explicit_count
            ),
            "inferred_count": (
                self.inferred_count
            ),
            "strong_count": (
                self.strong_count
            ),
            "minimum_distance": (
                None
                if self.minimum_distance is None
                else float(
                    self.minimum_distance
                )
            ),
            "mean_distance": (
                None
                if self.mean_distance is None
                else float(
                    self.mean_distance
                )
            ),
            "maximum_dha_angle": (
                None
                if self.maximum_dha_angle is None
                else float(
                    self.maximum_dha_angle
                )
            ),
            "classifications": sorted(
                self.classifications
            ),
            "directions": sorted(
                self.directions
            ),
            "metadata": (
                _serialize_hbond_statistics_value(
                    self.metadata
                )
            ),
        }

        if include_bonds:
            result[
                "hydrogen_bonds"
            ] = [
                hydrogen_bond.to_dict(
                    include_atoms=include_atoms
                )
                for hydrogen_bond
                in self.hydrogen_bonds
            ]

        return result


# -----------------------------------------------------------------------------
# Complete hydrogen-bond analysis result
# -----------------------------------------------------------------------------

@dataclass(
    frozen=True,
    slots=True,
)
class HydrogenBondAnalysisResult:
    """
    Complete result of a ligand-receptor hydrogen-bond analysis.

    Parameters
    ----------
    hydrogen_bonds : sequence of HydrogenBond
        Detected hydrogen bonds.
    residue_hydrogen_bonds : sequence of ResidueHydrogenBond
        Residue-grouped interaction results.
    ligand_atoms : sequence of atom-like
        Ligand atoms used in the analysis.
    receptor_atoms : sequence of atom-like
        Receptor atoms used in the analysis.
    donor_acceptor_cutoff : Number
        Maximum D...A distance used by the analysis.
    hydrogen_acceptor_cutoff : Number or None
        Maximum H...A distance.
    minimum_dha_angle : Number or None
        Minimum explicit D-H...A angle.
    minimum_inferred_angle : Number or None
        Minimum angle used for inferred interactions.
    statistics : mapping, optional
        Precomputed summary statistics.
    metadata : mapping, optional
        Additional analysis metadata.
    """

    hydrogen_bonds: Sequence[
        HydrogenBond
    ] = field(
        default_factory=tuple
    )

    residue_hydrogen_bonds: Sequence[
        ResidueHydrogenBond
    ] = field(
        default_factory=tuple
    )

    ligand_atoms: Sequence[
        AtomLike
    ] = field(
        default_factory=tuple
    )

    receptor_atoms: Sequence[
        AtomLike
    ] = field(
        default_factory=tuple
    )

    donor_acceptor_cutoff: np.float64 = (
        DEFAULT_DONOR_ACCEPTOR_DISTANCE
    )

    hydrogen_acceptor_cutoff: Optional[
        np.float64
    ] = DEFAULT_HYDROGEN_ACCEPTOR_DISTANCE

    minimum_dha_angle: Optional[
        np.float64
    ] = DEFAULT_MINIMUM_DHA_ANGLE

    minimum_inferred_angle: Optional[
        np.float64
    ] = DEFAULT_MINIMUM_INFERRED_ANGLE

    statistics: Mapping[
        str,
        Any,
    ] = field(
        default_factory=lambda: _EMPTY_METADATA,
        repr=False,
        compare=False,
    )

    metadata: Mapping[
        str,
        Any,
    ] = field(
        default_factory=lambda: _EMPTY_METADATA,
        repr=False,
        compare=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Validate and normalize the complete result."""

        normalized_bonds = tuple(
            self.hydrogen_bonds
        )

        for index, hydrogen_bond in enumerate(
            normalized_bonds
        ):
            if not isinstance(
                hydrogen_bond,
                HydrogenBond,
            ):
                raise TypeError(
                    "All hydrogen_bonds entries must be "
                    "HydrogenBond instances. Invalid entry "
                    f"at index {index}."
                )

        normalized_residue_results = tuple(
            self.residue_hydrogen_bonds
        )

        for index, residue_result in enumerate(
            normalized_residue_results
        ):
            if not isinstance(
                residue_result,
                ResidueHydrogenBond,
            ):
                raise TypeError(
                    "All residue_hydrogen_bonds entries must be "
                    "ResidueHydrogenBond instances. Invalid entry "
                    f"at index {index}."
                )

        ligand_atoms = tuple(
            self.ligand_atoms
        )

        receptor_atoms = tuple(
            self.receptor_atoms
        )

        donor_acceptor_cutoff = (
            _optional_float64(
                self.donor_acceptor_cutoff,
                name="donor-acceptor cutoff",
                minimum=0.0,
            )
        )

        if donor_acceptor_cutoff is None:
            raise ValueError(
                "Donor-acceptor cutoff cannot be None."
            )

        object.__setattr__(
            self,
            "hydrogen_bonds",
            normalized_bonds,
        )

        object.__setattr__(
            self,
            "residue_hydrogen_bonds",
            normalized_residue_results,
        )

        object.__setattr__(
            self,
            "ligand_atoms",
            ligand_atoms,
        )

        object.__setattr__(
            self,
            "receptor_atoms",
            receptor_atoms,
        )

        object.__setattr__(
            self,
            "donor_acceptor_cutoff",
            donor_acceptor_cutoff,
        )

        object.__setattr__(
            self,
            "hydrogen_acceptor_cutoff",
            _optional_float64(
                self.hydrogen_acceptor_cutoff,
                name="hydrogen-acceptor cutoff",
                minimum=0.0,
            ),
        )

        object.__setattr__(
            self,
            "minimum_dha_angle",
            _optional_float64(
                self.minimum_dha_angle,
                name="minimum D-H-A angle",
                minimum=MINIMUM_VALID_ANGLE_DEGREES,
                maximum=MAXIMUM_VALID_ANGLE_DEGREES,
            ),
        )

        object.__setattr__(
            self,
            "minimum_inferred_angle",
            _optional_float64(
                self.minimum_inferred_angle,
                name="minimum inferred angle",
                minimum=MINIMUM_VALID_ANGLE_DEGREES,
                maximum=MAXIMUM_VALID_ANGLE_DEGREES,
            ),
        )

        object.__setattr__(
            self,
            "statistics",
            _freeze_metadata(
                self.statistics
            ),
        )

        object.__setattr__(
            self,
            "metadata",
            _freeze_metadata(
                self.metadata
            ),
        )

    @property
    def hydrogen_bond_count(
        self,
    ) -> int:
        """
        Return the total hydrogen-bond count.

        Returns
        -------
        int
            Number of detected hydrogen bonds.
        """

        return len(
            self.hydrogen_bonds
        )

    @property
    def residue_count(
        self,
    ) -> int:
        """
        Return the number of grouped residues.

        Returns
        -------
        int
            Residue count.
        """

        return len(
            self.residue_hydrogen_bonds
        )

    @property
    def ligand_atom_count(
        self,
    ) -> int:
        """
        Return the number of analyzed ligand atoms.

        Returns
        -------
        int
            Ligand atom count.
        """

        return len(
            self.ligand_atoms
        )

    @property
    def receptor_atom_count(
        self,
    ) -> int:
        """
        Return the number of analyzed receptor atoms.

        Returns
        -------
        int
            Receptor atom count.
        """

        return len(
            self.receptor_atoms
        )

    @property
    def minimum_distance(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the minimum donor-acceptor distance.

        Returns
        -------
        numpy.float64 or None
            Minimum D...A distance.
        """

        if not self.hydrogen_bonds:
            return None

        return np.float64(
            min(
                hydrogen_bond
                .donor_acceptor_distance
                for hydrogen_bond
                in self.hydrogen_bonds
            )
        )

    @property
    def mean_distance(
        self,
    ) -> Optional[
        np.float64
    ]:
        """
        Return the mean donor-acceptor distance.

        Returns
        -------
        numpy.float64 or None
            Mean D...A distance.
        """

        if not self.hydrogen_bonds:
            return None

        return np.float64(
            np.mean(
                np.asarray(
                    [
                        hydrogen_bond
                        .donor_acceptor_distance
                        for hydrogen_bond
                        in self.hydrogen_bonds
                    ],
                    dtype=np.float64,
                )
            )
        )

    @property
    def explicit_count(
        self,
    ) -> int:
        """
        Return the number of explicit hydrogen bonds.

        Returns
        -------
        int
            Explicit-bond count.
        """

        return sum(
            hydrogen_bond.is_explicit
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def inferred_count(
        self,
    ) -> int:
        """
        Return the number of inferred hydrogen bonds.

        Returns
        -------
        int
            Inferred-bond count.
        """

        return (
            self.hydrogen_bond_count
            - self.explicit_count
        )

    @property
    def moderate_count(
        self,
    ) -> int:
        """Return the number of moderate hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_MODERATE
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def weak_count(
        self,
    ) -> int:
        """Return the number of weak hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_WEAK
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def unknown_count(
        self,
    ) -> int:
        """Return the number of unclassified hydrogen bonds."""

        return sum(
            hydrogen_bond.classification == HBOND_TYPE_UNKNOWN
            for hydrogen_bond in self.hydrogen_bonds
        )

    @property
    def strong_count(
        self,
    ) -> int:
        """
        Return the number of strong hydrogen bonds.

        Returns
        -------
        int
            Strong-bond count.
        """

        return sum(
            hydrogen_bond.is_strong
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def ligand_donor_count(
        self,
    ) -> int:
        """
        Return bonds in which the ligand is the donor.

        Returns
        -------
        int
            Ligand-donor bond count.
        """

        return sum(
            hydrogen_bond.is_ligand_donor
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def receptor_donor_count(
        self,
    ) -> int:
        """
        Return bonds in which the receptor is the donor.

        Returns
        -------
        int
            Receptor-donor bond count.
        """

        return sum(
            hydrogen_bond.is_receptor_donor
            for hydrogen_bond
            in self.hydrogen_bonds
        )

    @property
    def has_hydrogen_bonds(
        self,
    ) -> bool:
        """
        Whether at least one hydrogen bond was detected.

        Returns
        -------
        bool
            Hydrogen-bond presence.
        """

        return bool(
            self.hydrogen_bonds
        )

    @property
    def has_explicit_bonds(
        self,
    ) -> bool:
        """
        Whether explicit hydrogen bonds were detected.

        Returns
        -------
        bool
            Explicit-bond presence.
        """

        return self.explicit_count > 0

    @property
    def has_inferred_bonds(
        self,
    ) -> bool:
        """
        Whether inferred hydrogen bonds were detected.

        Returns
        -------
        bool
            Inferred-bond presence.
        """

        return self.inferred_count > 0

    @property
    def has_strong_bonds(
        self,
    ) -> bool:
        """
        Whether strong hydrogen bonds were detected.

        Returns
        -------
        bool
            Strong-bond presence.
        """

        return self.strong_count > 0

    def by_classification(
        self,
        classification: str,
    ) -> Tuple[HydrogenBond, ...]:
        """Return hydrogen bonds with one classification."""

        return self.bonds_by_classification(
            classification
        )

    def by_mode(
        self,
        mode: str,
    ) -> Tuple[HydrogenBond, ...]:
        """Return hydrogen bonds detected in one mode."""

        return self.bonds_by_mode(
            mode
        )

    def by_direction(
        self,
        direction: str,
    ) -> Tuple[HydrogenBond, ...]:
        """Return hydrogen bonds with one donor direction."""

        return self.bonds_by_direction(
            direction
        )

    def bonds_by_classification(
        self,
        classification: str,
    ) -> Tuple[
        HydrogenBond,
        ...,
    ]:
        """
        Return hydrogen bonds with one classification.

        Parameters
        ----------
        classification : str
            Requested classification.

        Returns
        -------
        tuple of HydrogenBond
            Matching interactions.
        """

        normalized = (
            validate_hydrogen_bond_classification(
                classification
            )
        )

        return tuple(
            hydrogen_bond
            for hydrogen_bond
            in self.hydrogen_bonds
            if hydrogen_bond.classification
            == normalized
        )

    def bonds_by_mode(
        self,
        mode: str,
    ) -> Tuple[
        HydrogenBond,
        ...,
    ]:
        """
        Return hydrogen bonds detected in one mode.

        Parameters
        ----------
        mode : str
            Explicit or inferred mode.

        Returns
        -------
        tuple of HydrogenBond
            Matching interactions.
        """

        normalized = (
            validate_hydrogen_bond_mode(
                mode
            )
        )

        return tuple(
            hydrogen_bond
            for hydrogen_bond
            in self.hydrogen_bonds
            if hydrogen_bond.mode
            == normalized
        )

    def bonds_by_direction(
        self,
        direction: str,
    ) -> Tuple[
        HydrogenBond,
        ...,
    ]:
        """
        Return hydrogen bonds with one donor direction.

        Parameters
        ----------
        direction : str
            Requested direction.

        Returns
        -------
        tuple of HydrogenBond
            Matching interactions.
        """

        normalized = (
            validate_hydrogen_bond_direction(
                direction
            )
        )

        return tuple(
            hydrogen_bond
            for hydrogen_bond
            in self.hydrogen_bonds
            if hydrogen_bond.direction
            == normalized
        )

    def get_residue_hydrogen_bond(
        self,
        key: ResidueContactKey,
    ) -> Optional[
        ResidueHydrogenBond
    ]:
        """
        Return the residue-level result associated with a key.

        Parameters
        ----------
        key : ResidueContactKey
            Residue key.

        Returns
        -------
        ResidueHydrogenBond or None
            Matching result.
        """

        normalized_key = (
            _normalize_residue_key(
                key
            )
        )

        for residue_result in (
            self.residue_hydrogen_bonds
        ):
            if (
                residue_result.key
                == normalized_key
            ):
                return residue_result

        return None

    def __getitem__(
        self,
        key: str,
    ) -> Any:
        """Return one attached statistics value."""

        return self.statistics[
            key
        ]

    def get(
        self,
        key: str,
        default: Any = None,
    ) -> Any:
        """Return one attached statistics value when present."""

        return self.statistics.get(
            key,
            default,
        )

    def keys(
        self,
    ) -> Any:
        """Return attached statistics keys."""

        return self.statistics.keys()

    def items(
        self,
    ) -> Any:
        """Return attached statistics items."""

        return self.statistics.items()

    def values(
        self,
    ) -> Any:
        """Return attached statistics values."""

        return self.statistics.values()

    def __contains__(
        self,
        key: object,
    ) -> bool:
        return key in self.statistics

    def to_dict(
        self,
        *,
        include_bonds: bool = True,
        include_residues: bool = True,
        include_atoms: bool = False,
    ) -> Dict[
        str,
        Any,
    ]:
        """
        Serialize the complete analysis result.

        Parameters
        ----------
        include_bonds : bool, optional
            Whether individual hydrogen bonds should be included.
        include_residues : bool, optional
            Whether residue-grouped results should be included.
        include_atoms : bool, optional
            Whether raw atom and residue objects should be included.

        Returns
        -------
        dict
            Serializable analysis representation.
        """

        result: Dict[
            str,
            Any,
        ] = {
            "hydrogen_bond_count": (
                self.hydrogen_bond_count
            ),
            "residue_count": (
                self.residue_count
            ),
            "ligand_atom_count": (
                self.ligand_atom_count
            ),
            "receptor_atom_count": (
                self.receptor_atom_count
            ),
            "explicit_count": (
                self.explicit_count
            ),
            "inferred_count": (
                self.inferred_count
            ),
            "strong_count": (
                self.strong_count
            ),
            "ligand_donor_count": (
                self.ligand_donor_count
            ),
            "receptor_donor_count": (
                self.receptor_donor_count
            ),
            "ligand_atoms": tuple(
                _safe_atom_identifier(atom)
                for atom in self.ligand_atoms
            ),
            "receptor_atoms": tuple(
                _safe_atom_identifier(atom)
                for atom in self.receptor_atoms
            ),
            "cutoffs": {
                "donor_acceptor": float(
                    self.donor_acceptor_cutoff
                ),
                "hydrogen_acceptor": (
                    None
                    if self.hydrogen_acceptor_cutoff is None
                    else float(
                        self.hydrogen_acceptor_cutoff
                    )
                ),
                "minimum_dha_angle": (
                    None
                    if self.minimum_dha_angle is None
                    else float(
                        self.minimum_dha_angle
                    )
                ),
                "minimum_inferred_angle": (
                    None
                    if self.minimum_inferred_angle is None
                    else float(
                        self.minimum_inferred_angle
                    )
                ),
            },
            "minimum_distance": (
                None
                if self.minimum_distance is None
                else float(
                    self.minimum_distance
                )
            ),
            "mean_distance": (
                None
                if self.mean_distance is None
                else float(
                    self.mean_distance
                )
            ),
            "donor_acceptor_cutoff": float(
                self.donor_acceptor_cutoff
            ),
            "hydrogen_acceptor_cutoff": (
                None
                if self.hydrogen_acceptor_cutoff
                is None
                else float(
                    self.hydrogen_acceptor_cutoff
                )
            ),
            "minimum_dha_angle": (
                None
                if self.minimum_dha_angle
                is None
                else float(
                    self.minimum_dha_angle
                )
            ),
            "minimum_inferred_angle": (
                None
                if self.minimum_inferred_angle
                is None
                else float(
                    self.minimum_inferred_angle
                )
            ),
            "has_hydrogen_bonds": (
                self.has_hydrogen_bonds
            ),
            "has_explicit_bonds": (
                self.has_explicit_bonds
            ),
            "has_inferred_bonds": (
                self.has_inferred_bonds
            ),
            "has_strong_bonds": (
                self.has_strong_bonds
            ),
            "statistics": (
                serialize_hydrogen_bond_statistics(
                    self.statistics
                )
            ),
            "metadata": (
                _serialize_hbond_statistics_value(
                    self.metadata
                )
            ),
        }

        if include_bonds:
            result[
                "hydrogen_bonds"
            ] = [
                hydrogen_bond.to_dict(
                    include_atoms=include_atoms
                )
                for hydrogen_bond
                in self.hydrogen_bonds
            ]

        if include_residues:
            result[
                "residue_hydrogen_bonds"
            ] = [
                residue_result.to_dict(
                    include_bonds=include_bonds,
                    include_atoms=include_atoms,
                )
                for residue_result
                in self.residue_hydrogen_bonds
            ]

        if include_atoms:
            result[
                "ligand_atoms"
            ] = self.ligand_atoms

            result[
                "receptor_atoms"
            ] = self.receptor_atoms

        return result


