# Public interface
# -----------------------------------------------------------------------------

_SECTION_3_PUBLIC_NAMES: Final[
    Tuple[
        str,
        ...,
    ]
] = (
    "HydrogenBondGeometry",
    "HydrogenBond",
    "ResidueHydrogenBond",
    "HydrogenBondAnalysisResult",
)

for public_name in _SECTION_3_PUBLIC_NAMES:
    if public_name not in __all__:
        __all__.append(
            public_name
        )


