# -----------------------------------------------------------------------------
# Numeric summary helpers
# -----------------------------------------------------------------------------

def _normalize_statistics_ddof(
    ddof: int,
) -> int:
    """
    Validate a statistical delta degrees of freedom.

    Parameters
    ----------
    ddof : int
        Delta degrees of freedom.

    Returns
    -------
    int
        Validated nonnegative integer.

    Raises
    ------
    TypeError
        If ``ddof`` is not an integer.
    ValueError
        If ``ddof`` is negative.
    """

    if isinstance(
        ddof,
        bool,
    ) or not isinstance(
        ddof,
        (
            int,
            np.integer,
        ),
    ):
        raise TypeError(
            "ddof must be an integer."
        )

    normalized_ddof = int(
        ddof
    )

    if normalized_ddof < 0:
        raise ValueError(
            "ddof must be nonnegative."
        )

    return normalized_ddof


def _normalize_summary_limit(
    value: int,
    *,
    name: str,
) -> int:
    """
    Validate a nonnegative summary limit.

    Parameters
    ----------
    value : int
        Requested limit.
    name : str
        Human-readable parameter name.

    Returns
    -------
    int
        Validated limit.
    """

    normalized_value = (
        _optional_nonnegative_integer(
            value,
            name=name,
        )
    )

    if normalized_value is None:
        return 0

    return normalized_value


def _finite_float_array(
    values: Iterable[
        Optional[
            Number
        ]
    ],
) -> FloatArray:
    """Return finite values as a one-dimensional ``float64`` array."""

    if isinstance(
        values,
        np.ndarray,
    ):
        try:
            numeric_values = np.asarray(
                values,
                dtype=np.float64,
            ).ravel()

        except (
            TypeError,
            ValueError,
            OverflowError,
        ):
            pass

        else:
            finite_mask = np.isfinite(
                numeric_values
            )

            if bool(
                np.all(
                    finite_mask
                )
            ):
                return numeric_values

            return numeric_values[
                finite_mask
            ]

    normalized_values: List[
        np.float64
    ] = []

    for value in values:
        if value is None:
            continue

        try:
            numeric_value = np.float64(
                value
            )

        except (
            TypeError,
            ValueError,
            OverflowError,
        ):
            continue

        if np.isfinite(
            numeric_value
        ):
            normalized_values.append(
                numeric_value
            )

    return np.asarray(
        normalized_values,
        dtype=np.float64,
    )


def _small_linear_quartiles(
    values: FloatArray,
) -> Tuple[
    np.float64,
    np.float64,
    np.float64,
]:
    """Return NumPy-compatible linear quartiles for a small array."""

    sorted_values = np.sort(
        values
    )

    positions = (
        np.float64(
            sorted_values.size
            - 1
        )
        * np.asarray(
            (
                0.25,
                0.50,
                0.75,
            ),
            dtype=np.float64,
        )
    )

    lower_indices = np.floor(
        positions
    ).astype(
        np.intp
    )

    upper_indices = np.ceil(
        positions
    ).astype(
        np.intp
    )

    fractions = positions - lower_indices

    lower_values = sorted_values[
        lower_indices
    ]

    upper_values = sorted_values[
        upper_indices
    ]

    differences = upper_values - lower_values

    quartiles = lower_values + differences * fractions

    upper_weight_mask = fractions >= np.float64(
        0.5
    )

    quartiles[
        upper_weight_mask
    ] = (
        upper_values[
            upper_weight_mask
        ]
        - differences[
            upper_weight_mask
        ]
        * (
            np.float64(
                1.0
            )
            - fractions[
                upper_weight_mask
            ]
        )
    )

    return (
        np.float64(
            quartiles[
                0
            ]
        ),
        np.float64(
            quartiles[
                1
            ]
        ),
        np.float64(
            quartiles[
                2
            ]
        ),
    )


def summarize_numeric_values(
    values: Iterable[
        Optional[
            Number
        ]
    ],
    *,
    ddof: int = DEFAULT_STATISTICS_DDOF,
    include_values: bool = False,
) -> Dict[
    str,
    Any,
]:
    """
    Calculate descriptive statistics for numeric values.

    Parameters
    ----------
    values : iterable of Number or None
        Values to summarize.
    ddof : int, optional
        Delta degrees of freedom for variance and standard deviation.
    include_values : bool, optional
        Whether the normalized values should be included.

    Returns
    -------
    dict
        Descriptive statistics.

    Notes
    -----
    Nonfinite values and ``None`` entries are ignored.
    """

    normalized_ddof = _normalize_statistics_ddof(
        ddof
    )

    numeric_values = _finite_float_array(
        values
    )

    count = int(
        numeric_values.size
    )

    if count == 0:
        result: Dict[
            str,
            Any,
        ] = {
            "count": 0,
            "minimum": None,
            "maximum": None,
            "mean": None,
            "median": None,
            "standard_deviation": None,
            "variance": None,
            "first_quartile": None,
            "third_quartile": None,
            "interquartile_range": None,
            "sum": np.float64(
                0.0
            ),
        }

        if include_values:
            result[
                "values"
            ] = ()

        return result

    if count <= 64:
        (
            first_quartile,
            median,
            third_quartile,
        ) = _small_linear_quartiles(
            numeric_values
        )

    else:
        (
            first_quartile,
            median,
            third_quartile,
        ) = np.percentile(
            numeric_values,
            (
                25.0,
                50.0,
                75.0,
            ),
        )

    if count > normalized_ddof:
        variance = np.float64(
            np.var(
                numeric_values,
                ddof=normalized_ddof,
                dtype=np.float64,
            )
        )

        standard_deviation = np.float64(
            np.sqrt(
                variance
            )
        )

    else:
        variance = None
        standard_deviation = None

    result = {
        "count": count,
        "minimum": np.float64(
            np.min(
                numeric_values
            )
        ),
        "maximum": np.float64(
            np.max(
                numeric_values
            )
        ),
        "mean": np.float64(
            np.mean(
                numeric_values,
                dtype=np.float64,
            )
        ),
        "median": np.float64(
            median
        ),
        "standard_deviation": (
            standard_deviation
        ),
        "variance": variance,
        "first_quartile": np.float64(
            first_quartile
        ),
        "third_quartile": np.float64(
            third_quartile
        ),
        "interquartile_range": np.float64(
            third_quartile
            - first_quartile
        ),
        "sum": np.float64(
            np.sum(
                numeric_values,
                dtype=np.float64,
            )
        ),
    }

    if include_values:
        result[
            "values"
        ] = tuple(
            np.float64(
                value
            )
            for value in numeric_values
        )

    return result


def _serialize_numeric_summary(
    summary: Mapping[
        str,
        Any,
    ],
) -> Dict[
    str,
    Any,
]:
    """
    Convert NumPy values in a numeric summary to Python scalars.

    Parameters
    ----------
    summary : mapping
        Numeric summary.

    Returns
    -------
    dict
        Serializable summary.
    """

    serialized: Dict[
        str,
        Any,
    ] = {}

    for key, value in summary.items():
        if isinstance(
            value,
            np.ndarray,
        ):
            serialized[
                key
            ] = value.tolist()

        elif isinstance(
            value,
            (
                np.integer,
            ),
        ):
            serialized[
                key
            ] = int(
                value
            )

        elif isinstance(
            value,
            (
                np.floating,
            ),
        ):
            serialized[
                key
            ] = float(
                value
            )

        elif isinstance(
            value,
            tuple,
        ):
            serialized[
                key
            ] = [
                float(
                    item
                )
                if isinstance(
                    item,
                    (
                        float,
                        np.floating,
                    ),
                )
                else item
                for item in value
            ]

        else:
            serialized[
                key
            ] = value

    return serialized


# -----------------------------------------------------------------------------
# Hydrogen-bond collection validation
# -----------------------------------------------------------------------------

def _normalize_hydrogen_bond_collection(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
    *,
    name: str = "hydrogen bonds",
) -> Tuple[
    HydrogenBond,
    ...,
]:
    """
    Validate a hydrogen-bond collection.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.
    name : str, optional
        Human-readable collection name.

    Returns
    -------
    tuple of HydrogenBond
        Validated collection.
    """

    try:
        normalized_bonds = tuple(
            hydrogen_bonds
        )

    except TypeError as error:
        raise TypeError(
            f"{name} must be an iterable of HydrogenBond objects."
        ) from error

    for index, hydrogen_bond in enumerate(
        normalized_bonds
    ):
        if not isinstance(
            hydrogen_bond,
            HydrogenBond,
        ):
            raise TypeError(
                f"All {name} entries must be HydrogenBond instances. "
                f"Invalid entry at index {index}."
            )

    return normalized_bonds


def _normalize_residue_hbond_collection(
    residue_groups: Iterable[
        ResidueHydrogenBond
    ],
) -> Tuple[
    ResidueHydrogenBond,
    ...,
]:
    """
    Validate residue-level hydrogen-bond groups.

    Parameters
    ----------
    residue_groups : iterable of ResidueHydrogenBond
        Residue groups.

    Returns
    -------
    tuple of ResidueHydrogenBond
        Validated groups.
    """

    try:
        normalized_groups = tuple(
            residue_groups
        )

    except TypeError as error:
        raise TypeError(
            "residue_groups must be iterable."
        ) from error

    for index, residue_group in enumerate(
        normalized_groups
    ):
        if not isinstance(
            residue_group,
            ResidueHydrogenBond,
        ):
            raise TypeError(
                "All residue groups must be ResidueHydrogenBond "
                f"instances. Invalid entry at index {index}."
            )

    return normalized_groups


# -----------------------------------------------------------------------------
# Basic count summaries
# -----------------------------------------------------------------------------

def hydrogen_bond_mode_counts(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    HydrogenBondMode,
    int,
]:
    """
    Count hydrogen bonds by analysis mode.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Explicit and inferred counts.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    counts: Dict[
        HydrogenBondMode,
        int,
    ] = {
        HBOND_MODE_EXPLICIT: 0,
        HBOND_MODE_INFERRED: 0,
    }

    for hydrogen_bond in normalized_bonds:
        mode = validate_hydrogen_bond_mode(
            hydrogen_bond.mode
        )

        counts[
            mode
        ] = counts.get(
            mode,
            0,
        ) + 1

    return counts


def hydrogen_bond_direction_counts(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    HydrogenBondDirection,
    int,
]:
    """
    Count hydrogen bonds by donor direction.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Direction counts.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    counts: Dict[
        HydrogenBondDirection,
        int,
    ] = {
        HBOND_DIRECTION_LIGAND_DONOR: 0,
        HBOND_DIRECTION_RECEPTOR_DONOR: 0,
        HBOND_DIRECTION_UNKNOWN: 0,
    }

    for hydrogen_bond in normalized_bonds:
        direction = (
            validate_hydrogen_bond_direction(
                hydrogen_bond.direction
            )
        )

        counts[
            direction
        ] = counts.get(
            direction,
            0,
        ) + 1

    return counts


def hydrogen_bond_role_counts(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    str,
    int,
]:
    """
    Count ligand and receptor donor/acceptor roles.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Role counts.
    """

    direction_counts = (
        hydrogen_bond_direction_counts(
            hydrogen_bonds
        )
    )

    ligand_donor_count = direction_counts.get(
        HBOND_DIRECTION_LIGAND_DONOR,
        0,
    )

    receptor_donor_count = direction_counts.get(
        HBOND_DIRECTION_RECEPTOR_DONOR,
        0,
    )

    unknown_count = direction_counts.get(
        HBOND_DIRECTION_UNKNOWN,
        0,
    )

    return {
        "ligand_donor_count": (
            ligand_donor_count
        ),
        "ligand_acceptor_count": (
            receptor_donor_count
        ),
        "receptor_donor_count": (
            receptor_donor_count
        ),
        "receptor_acceptor_count": (
            ligand_donor_count
        ),
        "unknown_direction_count": (
            unknown_count
        ),
        HBOND_ROLE_DONOR: (
            ligand_donor_count
            + receptor_donor_count
            + unknown_count
        ),
        HBOND_ROLE_ACCEPTOR: (
            ligand_donor_count
            + receptor_donor_count
            + unknown_count
        ),
    }


def count_unique_hbond_atoms(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    str,
    int,
]:
    """
    Count unique atoms participating in hydrogen bonds.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Unique donor, acceptor and hydrogen counts.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    donor_ids = {
        id(
            hydrogen_bond.donor
        )
        for hydrogen_bond in normalized_bonds
    }

    acceptor_ids = {
        id(
            hydrogen_bond.acceptor
        )
        for hydrogen_bond in normalized_bonds
    }

    hydrogen_ids = {
        id(
            hydrogen_bond.hydrogen
        )
        for hydrogen_bond in normalized_bonds
        if hydrogen_bond.hydrogen is not None
    }

    all_heavy_atom_ids = donor_ids | acceptor_ids

    return {
        "unique_donor_count": len(
            donor_ids
        ),
        "unique_acceptor_count": len(
            acceptor_ids
        ),
        "unique_explicit_hydrogen_count": len(
            hydrogen_ids
        ),
        "unique_hydrogen_count": len(
            hydrogen_ids
        ),
        "unique_heavy_atom_count": len(
            all_heavy_atom_ids
        ),
    }


# -----------------------------------------------------------------------------
# Geometric value extraction
# -----------------------------------------------------------------------------

def collect_hydrogen_bond_distances(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    str,
    FloatArray,
]:
    """
    Collect hydrogen-bond distance measurements.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Arrays for D...A, H...A and D-H distances.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    return {
        "donor_acceptor": _finite_float_array(
            hydrogen_bond
            .donor_acceptor_distance
            for hydrogen_bond
            in normalized_bonds
        ),
        "hydrogen_acceptor": _finite_float_array(
            hydrogen_bond
            .hydrogen_acceptor_distance
            for hydrogen_bond
            in normalized_bonds
        ),
        "donor_hydrogen": _finite_float_array(
            hydrogen_bond
            .geometry
            .donor_hydrogen_distance
            for hydrogen_bond
            in normalized_bonds
        ),
    }


def collect_hydrogen_bond_angles(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
) -> Dict[
    str,
    FloatArray,
]:
    """
    Collect hydrogen-bond angular measurements.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.

    Returns
    -------
    dict
        Arrays for explicit and inferred angles.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    donor_deviations = _finite_float_array(
        hydrogen_bond.geometry.donor_angle
        for hydrogen_bond in normalized_bonds
    )

    acceptor_deviations = _finite_float_array(
        hydrogen_bond.geometry.acceptor_angle
        for hydrogen_bond in normalized_bonds
    )

    return {
        "dha": _finite_float_array(
            hydrogen_bond.dha_angle
            for hydrogen_bond in normalized_bonds
        ),
        "donor_deviation": donor_deviations,
        "acceptor_deviation": (
            acceptor_deviations
        ),
        "donor": donor_deviations.copy(),
        "acceptor": (
            acceptor_deviations.copy()
        ),
    }


def collect_hydrogen_bond_strength_scores(
    hydrogen_bonds: Iterable[
        HydrogenBond
    ],
    *,
    config: HydrogenBondClassificationConfig = (
        DEFAULT_HBOND_CLASSIFICATION_CONFIG
    ),
    recalculate: bool = (
        DEFAULT_RECALCULATE_STRENGTHS
    ),
) -> FloatArray:
    """
    Collect geometric-strength scores.

    Parameters
    ----------
    hydrogen_bonds : iterable of HydrogenBond
        Hydrogen bonds.
    config : HydrogenBondClassificationConfig, optional
        Classification configuration.
    recalculate : bool, optional
        Whether scores should always be recalculated.

    Returns
    -------
    numpy.ndarray
        Finite strength scores.
    """

    normalized_bonds = (
        _normalize_hydrogen_bond_collection(
            hydrogen_bonds
        )
    )

    scores: List[
        np.float64
    ] = []

    for hydrogen_bond in normalized_bonds:
        stored_score = hydrogen_bond.metadata.get(
            "geometric_strength_score"
        )

        if (
            not recalculate
            and stored_score is not None
        ):
            try:
                normalized_score = np.float64(
                    stored_score
                )

            except (
                TypeError,
                ValueError,
                OverflowError,
            ):
                normalized_score = np.float64(
                    np.nan
                )

            if np.isfinite(
                normalized_score
            ):
                scores.append(
                    normalized_score
                )

                continue

        strength = get_hydrogen_bond_strength(
            hydrogen_bond,
            config=config,
        )

        scores.append(
            strength.score
        )

    return _finite_float_array(
        scores
    )


