# -----------------------------------------------------------------------------
# Fake chemical element
# -----------------------------------------------------------------------------

@dataclass(
    frozen=True,
    slots=True,
)
class FakeElement:
    """
    Minimal chemical-element object used by self-tests.

    Parameters
    ----------
    name : str
        Element symbol.
    atomic_number : int
        Atomic number.
    """

    name: str
    atomic_number: int

    def __post_init__(
        self,
    ) -> None:
        """Normalize element attributes."""

        normalized_name = str(
            self.name
        ).strip().upper()

        if not normalized_name:
            raise ValueError(
                "FakeElement name cannot be empty."
            )

        if isinstance(
            self.atomic_number,
            bool,
        ) or not isinstance(
            self.atomic_number,
            (
                int,
                np.integer,
            ),
        ):
            raise TypeError(
                "FakeElement atomic_number must be an integer."
            )

        normalized_atomic_number = int(
            self.atomic_number
        )

        if normalized_atomic_number < 0:
            raise ValueError(
                "FakeElement atomic_number must be nonnegative."
            )

        object.__setattr__(
            self,
            "name",
            normalized_name,
        )

        object.__setattr__(
            self,
            "atomic_number",
            normalized_atomic_number,
        )

    @property
    def symbol(
        self,
    ) -> str:
        """Return the element symbol."""

        return self.name


_SELF_TEST_ELEMENT_DATA: Final[
    Mapping[
        str,
        Tuple[
            str,
            int,
        ],
    ]
] = MappingProxyType(
    {
        "H": (
            "H",
            1,
        ),
        "C": (
            "C",
            6,
        ),
        "N": (
            "N",
            7,
        ),
        "O": (
            "O",
            8,
        ),
        "F": (
            "F",
            9,
        ),
        "P": (
            "P",
            15,
        ),
        "S": (
            "S",
            16,
        ),
        "CL": (
            "CL",
            17,
        ),
        "BR": (
            "BR",
            35,
        ),
        "I": (
            "I",
            53,
        ),
        "NA": (
            "NA",
            11,
        ),
        "MG": (
            "MG",
            12,
        ),
        "CA": (
            "CA",
            20,
        ),
        "ZN": (
            "ZN",
            30,
        ),
        "FE": (
            "FE",
            26,
        ),
    }
)


def make_fake_element(
    symbol: str,
) -> FakeElement:
    """
    Create a fake chemical element.

    Parameters
    ----------
    symbol : str
        Element symbol.

    Returns
    -------
    FakeElement
        Element object.
    """

    normalized_symbol = str(
        symbol
    ).strip().upper()

    if not normalized_symbol:
        raise ValueError(
            "Element symbol cannot be empty."
        )

    element_name, atomic_number = (
        _SELF_TEST_ELEMENT_DATA.get(
            normalized_symbol,
            (
                normalized_symbol,
                0,
            ),
        )
    )

    return FakeElement(
        name=element_name,
        atomic_number=atomic_number,
    )


# -----------------------------------------------------------------------------
# Fake residue
# -----------------------------------------------------------------------------

@dataclass(
    slots=True,
    eq=False,
)
class FakeResidue:
    """
    Minimal residue-like object for hydrogen-bond self-tests.

    Parameters
    ----------
    name : str
        Residue name.
    number : int
        Residue number.
    chain_id : str, optional
        Chain identifier.
    insertion_code : str, optional
        Insertion code.
    polymer_type : str or None, optional
        Polymer classification.
    atoms : list, optional
        Residue atoms.
    """

    name: str
    number: int
    chain_id: str = SELF_TEST_DEFAULT_CHAIN_ID
    insertion_code: str = ""
    polymer_type: Optional[
        str
    ] = "amino"
    atoms: List[
        "FakeAtom"
    ] = field(
        default_factory=list,
        repr=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Normalize residue attributes."""

        self.name = str(
            self.name
        ).strip().upper()

        if not self.name:
            raise ValueError(
                "FakeResidue name cannot be empty."
            )

        if isinstance(
            self.number,
            bool,
        ) or not isinstance(
            self.number,
            (
                int,
                np.integer,
            ),
        ):
            raise TypeError(
                "FakeResidue number must be an integer."
            )

        self.number = int(
            self.number
        )

        self.chain_id = str(
            self.chain_id
        ).strip()

        self.insertion_code = str(
            self.insertion_code
        ).strip()

        if self.polymer_type is not None:
            self.polymer_type = str(
                self.polymer_type
            ).strip().lower()

    @property
    def id(
        self,
    ) -> int:
        """Return the residue number."""

        return self.number

    @property
    def chain(
        self,
    ) -> str:
        """Return the chain identifier."""

        return self.chain_id

    @property
    def atomspec(
        self,
    ) -> str:
        """Return a compact ChimeraX-like residue specification."""

        chain_component = (
            f"/{self.chain_id}"
            if self.chain_id
            else ""
        )

        insertion_component = (
            self.insertion_code
            if self.insertion_code
            else ""
        )

        return (
            f"{chain_component}:"
            f"{self.number}{insertion_component}"
        )

    def add_atom(
        self,
        atom: "FakeAtom",
    ) -> None:
        """
        Add an atom to the residue.

        Parameters
        ----------
        atom : FakeAtom
            Atom to add.
        """

        if not isinstance(
            atom,
            FakeAtom,
        ):
            raise TypeError(
                "atom must be a FakeAtom instance."
            )

        if atom not in self.atoms:
            self.atoms.append(
                atom
            )

        atom.residue = self


# -----------------------------------------------------------------------------
# Fake atom
# -----------------------------------------------------------------------------

@dataclass(
    slots=True,
    eq=False,
)
class FakeAtom:
    """
    Minimal ChimeraX-like atom used by self-tests.

    Parameters
    ----------
    name : str
        Atom name.
    element : str or FakeElement
        Chemical element.
    coord : array-like
        Cartesian coordinate in angstroms.
    residue : FakeResidue or None, optional
        Parent residue.
    atom_type : str or None, optional
        Atom-type label.
    formal_charge : Number, optional
        Formal charge.
    aromatic : bool, optional
        Aromaticity flag.
    index : int or None, optional
        Atom index.
    serial_number : int or None, optional
        Serial number.
    structure : Any, optional
        Parent structure.
    metadata : mapping, optional
        Additional attributes.
    """

    name: str
    element: Union[
        str,
        FakeElement,
    ]
    coord: Coordinate
    residue: Optional[
        FakeResidue
    ] = None
    atom_type: Optional[
        str
    ] = None
    formal_charge: np.float64 = np.float64(
        0.0
    )
    aromatic: bool = False
    index: Optional[
        int
    ] = None
    serial_number: Optional[
        int
    ] = None
    structure: Any = None
    metadata: MutableMapping[
        str,
        Any,
    ] = field(
        default_factory=dict,
        repr=False,
    )
    bonds: List[
        "FakeBond"
    ] = field(
        default_factory=list,
        repr=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Normalize atom attributes."""

        self.name = str(
            self.name
        ).strip().upper()

        if not self.name:
            raise ValueError(
                "FakeAtom name cannot be empty."
            )

        if isinstance(
            self.element,
            FakeElement,
        ):
            normalized_element = self.element

        else:
            normalized_element = make_fake_element(
                str(
                    self.element
                )
            )

        self.element = normalized_element

        normalized_coord = np.asarray(
            self.coord,
            dtype=np.float64,
        )

        if normalized_coord.shape != (
            3,
        ):
            raise ValueError(
                "FakeAtom coord must have shape (3,)."
            )

        if not np.all(
            np.isfinite(
                normalized_coord
            )
        ):
            raise ValueError(
                "FakeAtom coord must contain finite values."
            )

        self.coord = normalized_coord.copy()

        self.formal_charge = np.float64(
            self.formal_charge
        )

        if not np.isfinite(
            self.formal_charge
        ):
            raise ValueError(
                "FakeAtom formal_charge must be finite."
            )

        self.aromatic = bool(
            self.aromatic
        )

        if self.atom_type is not None:
            self.atom_type = str(
                self.atom_type
            ).strip()

        if self.index is not None:
            self.index = int(
                self.index
            )

        if self.serial_number is not None:
            self.serial_number = int(
                self.serial_number
            )

        if self.residue is not None:
            self.residue.add_atom(
                self
            )

    @property
    def scene_coord(
        self,
    ) -> Coordinate:
        """Return a ChimeraX-like scene coordinate."""

        return np.asarray(
            self.coord,
            dtype=np.float64,
        )

    @scene_coord.setter
    def scene_coord(
        self,
        value: Coordinate,
    ) -> None:
        """Set the scene coordinate."""

        self.coord = np.asarray(
            value,
            dtype=np.float64,
        ).copy()

    @property
    def idatm_type(
        self,
    ) -> Optional[
        str
    ]:
        """Return the atom-type label."""

        return self.atom_type

    @property
    def neighbors(
        self,
    ) -> Tuple[
        "FakeAtom",
        ...,
    ]:
        """Return directly bonded neighboring atoms."""

        neighboring_atoms: List[
            FakeAtom
        ] = []

        for bond in self.bonds:
            other_atom = bond.other_atom(
                self
            )

            if other_atom is not None:
                neighboring_atoms.append(
                    other_atom
                )

        return tuple(
            neighboring_atoms
        )

    @property
    def bonded_atoms(
        self,
    ) -> Tuple[
        "FakeAtom",
        ...,
    ]:
        """Return bonded atoms."""

        return self.neighbors

    @property
    def num_bonds(
        self,
    ) -> int:
        """Return the number of bonds."""

        return len(
            self.bonds
        )

    @property
    def is_aromatic(
        self,
    ) -> bool:
        """Return aromaticity."""

        return self.aromatic

    @property
    def atomspec(
        self,
    ) -> str:
        """Return a compact ChimeraX-like atom specification."""

        if self.residue is None:
            return f"@{self.name}"

        return (
            f"{self.residue.atomspec}"
            f"@{self.name}"
        )

    def add_bond(
        self,
        bond: "FakeBond",
    ) -> None:
        """
        Add a bond to the atom.

        Parameters
        ----------
        bond : FakeBond
            Bond to add.
        """

        if not isinstance(
            bond,
            FakeBond,
        ):
            raise TypeError(
                "bond must be a FakeBond instance."
            )

        if bond not in self.bonds:
            self.bonds.append(
                bond
            )

    def set_coord(
        self,
        coordinate: Coordinate,
    ) -> None:
        """
        Set the atom coordinate.

        Parameters
        ----------
        coordinate : array-like
            New Cartesian coordinate.
        """

        normalized_coordinate = np.asarray(
            coordinate,
            dtype=np.float64,
        )

        if normalized_coordinate.shape != (
            3,
        ):
            raise ValueError(
                "coordinate must have shape (3,)."
            )

        self.coord = normalized_coordinate.copy()


# -----------------------------------------------------------------------------
# Fake bond
# -----------------------------------------------------------------------------

@dataclass(
    slots=True,
    eq=False,
)
class FakeBond:
    """
    Minimal bond-like object for self-tests.

    Parameters
    ----------
    atom1 : FakeAtom
        First atom.
    atom2 : FakeAtom
        Second atom.
    order : Number, optional
        Bond order.
    aromatic : bool, optional
        Aromaticity flag.
    """

    atom1: FakeAtom
    atom2: FakeAtom
    order: np.float64 = np.float64(
        1.0
    )
    aromatic: bool = False

    def __post_init__(
        self,
    ) -> None:
        """Validate the bond and attach it to both atoms."""

        if not isinstance(
            self.atom1,
            FakeAtom,
        ) or not isinstance(
            self.atom2,
            FakeAtom,
        ):
            raise TypeError(
                "FakeBond atoms must be FakeAtom instances."
            )

        if self.atom1 is self.atom2:
            raise ValueError(
                "A FakeBond cannot connect an atom to itself."
            )

        self.order = np.float64(
            self.order
        )

        if (
            not np.isfinite(
                self.order
            )
            or self.order <= 0.0
        ):
            raise ValueError(
                "FakeBond order must be finite and positive."
            )

        self.aromatic = bool(
            self.aromatic
        )

        self.atom1.add_bond(
            self
        )

        self.atom2.add_bond(
            self
        )

    @property
    def atoms(
        self,
    ) -> Tuple[
        FakeAtom,
        FakeAtom,
    ]:
        """Return the bonded atoms."""

        return (
            self.atom1,
            self.atom2,
        )

    @property
    def bond_order(
        self,
    ) -> np.float64:
        """Return the bond order."""

        return self.order

    @property
    def is_aromatic(
        self,
    ) -> bool:
        """Return aromaticity."""

        return self.aromatic

    def other_atom(
        self,
        atom: FakeAtom,
    ) -> Optional[
        FakeAtom
    ]:
        """
        Return the atom on the opposite side of the bond.

        Parameters
        ----------
        atom : FakeAtom
            Query atom.

        Returns
        -------
        FakeAtom or None
            Opposite atom.
        """

        if atom is self.atom1:
            return self.atom2

        if atom is self.atom2:
            return self.atom1

        return None


# -----------------------------------------------------------------------------
# Fake atomic structure
# -----------------------------------------------------------------------------

@dataclass(
    slots=True,
    eq=False,
)
class FakeStructure:
    """
    Minimal atomic structure compatible with self-test pipelines.

    Parameters
    ----------
    name : str
        Structure name.
    atoms : sequence of FakeAtom, optional
        Structure atoms.
    residues : sequence of FakeResidue, optional
        Structure residues.
    model_id : str or int or None, optional
        Model identifier.
    metadata : mapping, optional
        Additional data.
    """

    name: str
    atoms: List[
        FakeAtom
    ] = field(
        default_factory=list,
    )
    residues: List[
        FakeResidue
    ] = field(
        default_factory=list,
    )
    model_id: Optional[
        Union[
            str,
            int,
        ]
    ] = None
    metadata: MutableMapping[
        str,
        Any,
    ] = field(
        default_factory=dict,
        repr=False,
    )

    def __post_init__(
        self,
    ) -> None:
        """Normalize structure data."""

        self.name = str(
            self.name
        ).strip()

        if not self.name:
            raise ValueError(
                "FakeStructure name cannot be empty."
            )

        initial_atoms = list(
            self.atoms
        )

        initial_residues = list(
            self.residues
        )

        self.atoms = []
        self.residues = []

        for residue in initial_residues:
            self.add_residue(
                residue
            )

        for atom in initial_atoms:
            self.add_atom(
                atom
            )

    @property
    def id_string(
        self,
    ) -> str:
        """Return a string model identifier."""

        if self.model_id is None:
            return self.name

        return str(
            self.model_id
        )

    @property
    def num_atoms(
        self,
    ) -> int:
        """Return the atom count."""

        return len(
            self.atoms
        )

    @property
    def num_residues(
        self,
    ) -> int:
        """Return the residue count."""

        return len(
            self.residues
        )

    def add_residue(
        self,
        residue: FakeResidue,
    ) -> None:
        """
        Add a residue to the structure.

        Parameters
        ----------
        residue : FakeResidue
            Residue to add.
        """

        if not isinstance(
            residue,
            FakeResidue,
        ):
            raise TypeError(
                "residue must be a FakeResidue instance."
            )

        if residue not in self.residues:
            self.residues.append(
                residue
            )

        for atom in tuple(
            residue.atoms
        ):
            self.add_atom(
                atom
            )

    def add_atom(
        self,
        atom: FakeAtom,
    ) -> None:
        """
        Add an atom to the structure.

        Parameters
        ----------
        atom : FakeAtom
            Atom to add.
        """

        if not isinstance(
            atom,
            FakeAtom,
        ):
            raise TypeError(
                "atom must be a FakeAtom instance."
            )

        if atom not in self.atoms:
            self.atoms.append(
                atom
            )

        atom.structure = self

        if atom.index is None:
            atom.index = self.atoms.index(
                atom
            )

        if atom.serial_number is None:
            atom.serial_number = (
                atom.index
                + 1
            )

        if atom.residue is not None:
            if atom.residue not in self.residues:
                self.residues.append(
                    atom.residue
                )

            if atom not in atom.residue.atoms:
                atom.residue.atoms.append(
                    atom
                )

    def add_bond(
        self,
        atom1: FakeAtom,
        atom2: FakeAtom,
        *,
        order: Number = 1.0,
        aromatic: bool = False,
    ) -> FakeBond:
        """
        Create a bond between two structure atoms.

        Parameters
        ----------
        atom1 : FakeAtom
            First atom.
        atom2 : FakeAtom
            Second atom.
        order : Number, optional
            Bond order.
        aromatic : bool, optional
            Aromaticity flag.

        Returns
        -------
        FakeBond
            Created bond.
        """

        if atom1 not in self.atoms:
            self.add_atom(
                atom1
            )

        if atom2 not in self.atoms:
            self.add_atom(
                atom2
            )

        return FakeBond(
            atom1=atom1,
            atom2=atom2,
            order=np.float64(
                order
            ),
            aromatic=aromatic,
        )

    def copy(
        self,
        *,
        name: Optional[
            str
        ] = None,
        coordinate_offset: Coordinate = (
            0.0,
            0.0,
            0.0,
        ),
    ) -> "FakeStructure":
        """
        Create a deep structural copy.

        Parameters
        ----------
        name : str or None, optional
            New structure name.
        coordinate_offset : array-like, optional
            Coordinate translation.

        Returns
        -------
        FakeStructure
            Independent structure copy.
        """

        offset = np.asarray(
            coordinate_offset,
            dtype=np.float64,
        )

        if offset.shape != (
            3,
        ):
            raise ValueError(
                "coordinate_offset must have shape (3,)."
            )

        copied_structure = FakeStructure(
            name=(
                self.name
                if name is None
                else name
            ),
            model_id=self.model_id,
            metadata=dict(
                self.metadata
            ),
        )

        residue_mapping: Dict[
            FakeResidue,
            FakeResidue,
        ] = {}

        atom_mapping: Dict[
            FakeAtom,
            FakeAtom,
        ] = {}

        for residue in self.residues:
            copied_residue = FakeResidue(
                name=residue.name,
                number=residue.number,
                chain_id=residue.chain_id,
                insertion_code=(
                    residue.insertion_code
                ),
                polymer_type=(
                    residue.polymer_type
                ),
            )

            copied_structure.add_residue(
                copied_residue
            )

            residue_mapping[
                residue
            ] = copied_residue

        for atom in self.atoms:
            copied_atom = FakeAtom(
                name=atom.name,
                element=atom.element,
                coord=(
                    np.asarray(
                        atom.coord,
                        dtype=np.float64,
                    )
                    + offset
                ),
                residue=(
                    None
                    if atom.residue is None
                    else residue_mapping[
                        atom.residue
                    ]
                ),
                atom_type=atom.atom_type,
                formal_charge=(
                    atom.formal_charge
                ),
                aromatic=atom.aromatic,
                index=atom.index,
                serial_number=(
                    atom.serial_number
                ),
                metadata=dict(
                    atom.metadata
                ),
            )

            copied_structure.add_atom(
                copied_atom
            )

            atom_mapping[
                atom
            ] = copied_atom

        seen_bonds: Set[
            int
        ] = set()

        for atom in self.atoms:
            for bond in atom.bonds:
                bond_identity = id(
                    bond
                )

                if bond_identity in seen_bonds:
                    continue

                seen_bonds.add(
                    bond_identity
                )

                copied_structure.add_bond(
                    atom_mapping[
                        bond.atom1
                    ],
                    atom_mapping[
                        bond.atom2
                    ],
                    order=bond.order,
                    aromatic=bond.aromatic,
                )

        return copied_structure


# -----------------------------------------------------------------------------
# Fake DockModel
# -----------------------------------------------------------------------------

@dataclass(
    slots=True,
    eq=False,
)
class FakeDockModel:
    """
    Minimal DockModel-like object for integration self-tests.

    Parameters
    ----------
    receptor : Any
        Receptor structure.
    ligand : Any or None, optional
        Active ligand.
    poses : mapping or sequence, optional
        Docking poses.
    active_pose : int or str or None, optional
        Active-pose selector.
    name : str, optional
        Model name.
    metadata : mapping, optional
        Mutable metadata storage.
    """

    receptor: Any
    ligand: Any = None
    poses: Any = field(
        default_factory=list
    )
    active_pose: Optional[
        Union[
            int,
            str,
        ]
    ] = None
    name: str = "fake_dock_model"
    metadata: MutableMapping[
        str,
        Any,
    ] = field(
        default_factory=dict
    )

    hydrogen_bond_result: Optional[
        HydrogenBondAnalysisResult
    ] = None

    hydrogen_bond_results: Any = None

    def __post_init__(
        self,
    ) -> None:
        """Normalize fake DockModel data."""

        self.name = str(
            self.name
        ).strip()

        if not self.name:
            raise ValueError(
                "FakeDockModel name cannot be empty."
            )

        if self.poses is None:
            self.poses = []

        if self.ligand is None:
            if isinstance(
                self.poses,
                Mapping,
            ) and self.poses:
                self.ligand = next(
                    iter(
                        self.poses.values()
                    )
                )

            else:
                try:
                    pose_sequence = tuple(
                        self.poses
                    )

                except TypeError:
                    pose_sequence = ()

                if pose_sequence:
                    self.ligand = (
                        pose_sequence[
                            0
                        ]
                    )

    @property
    def receptor_model(
        self,
    ) -> Any:
        """Return receptor alias."""

        return self.receptor

    @property
    def ligand_model(
        self,
    ) -> Any:
        """Return ligand alias."""

        return self.ligand

    @property
    def ligand_poses(
        self,
    ) -> Any:
        """Return poses alias."""

        return self.poses


