def _self_test_get_bonded_heavy_atoms(
) -> None:
    """Test bonded-heavy-atom extraction."""

    residue = make_fake_residue(
        "LIG",
        1,
        polymer_type=None,
    )

    nitrogen = make_fake_atom(
        "N",
        "N",
        (
            0.0,
            0.0,
            0.0,
        ),
        residue=residue,
    )

    carbon = make_fake_atom(
        "C",
        "C",
        (
            1.4,
            0.0,
            0.0,
        ),
        residue=residue,
    )

    hydrogen = make_fake_atom(
        "H",
        "H",
        (
            -1.0,
            0.0,
            0.0,
        ),
        residue=residue,
    )

    connect_fake_atoms(
        nitrogen,
        carbon,
    )

    connect_fake_atoms(
        nitrogen,
        hydrogen,
    )

    heavy_atoms = get_bonded_heavy_atoms(
        nitrogen
    )

    self_test_assert_equal(
        len(
            heavy_atoms
        ),
        1,
    )

    self_test_assert_is(
        heavy_atoms[
            0
        ],
        carbon,
    )


